with cleaned as (select *, cast(is_remote as int) as is_remote_flag from employees where job_title is not null) select id, email, job_title, salary, is_remote, is_remote_flag, lag(salary, 1) over (partition by dept_id order by hire_date, id) as prev_salary, sum(salary) over w_hist as running_salary from cleaned window w_hist as (partition by dept_id order by salary, id rows between unbounded preceding and current row);
